'use strict';

const https = require('https');
const http = require('http');
const { URL } = require('url');
const { DigitalPayeError } = require('./errors');

const DEFAULT_BASE_URL = 'https://api.digitalpaye.com';
const DEFAULT_TIMEOUT = 30000;

/**
 * Low-level HTTP client: handles Basic → Bearer token exchange (cached
 * until near expiry), request signing, JSON encoding/decoding, and
 * translates any non-success response into a DigitalPayeError.
 */
class Client {
  /**
   * @param {object} options
   * @param {string} options.publicKey  Your DigitalPaye API public key
   * @param {string} options.secret     Your DigitalPaye API secret key
   * @param {string} [options.baseUrl]  Override the API base URL (advanced/testing use only)
   * @param {number} [options.timeout]  Request timeout in ms (default 30000)
   */
  constructor(options = {}) {
    if (!options.publicKey || !options.secret) {
      throw new Error('DigitalPaye SDK: "publicKey" and "secret" are required.');
    }
    this.publicKey = options.publicKey;
    this.secret = options.secret;
    this.baseUrl = options.baseUrl || DEFAULT_BASE_URL;
    this.timeout = options.timeout || DEFAULT_TIMEOUT;

    this._token = null;
    this._tokenExpiresAt = 0;
  }

  // ── Basic Auth → Bearer token (cached) ─────────────────────────
  async _authenticate() {
    const creds = Buffer.from(`${this.publicKey}:${this.secret}`).toString('base64');

    const res = await this._rawRequest('POST', '/v1/auth/token', null, {
      Authorization: `Basic ${creds}`,
    });

    const body = res.body;
    if (res.status !== 200 || !body || !body.data || !body.data.access_token) {
      const message = (body && body.message) || 'Authentication failed. Please check your API keys.';
      throw new DigitalPayeError('Unauthorized', message, res.status || 401);
    }

    this._token = body.data.access_token;
    const expiresIn = body.data.expires_in || 600;
    this._tokenExpiresAt = Date.now() + expiresIn * 1000 - 30000; // renew 30s early

    return this._token;
  }

  async _ensureToken() {
    if (!this._token || Date.now() > this._tokenExpiresAt) {
      await this._authenticate();
    }
    return this._token;
  }

  /**
   * Perform an authenticated API request.
   *
   * @param {string} method       HTTP method
   * @param {string} path         Path starting with /v1/...
   * @param {object} [body]       Request body (for POST/PUT/PATCH)
   * @param {object} [opts]
   * @param {boolean} [opts.auth] Set to false to skip the Bearer token (default true)
   * @returns {Promise<{data: *, meta: *, message: string}>}
   */
  async request(method, path, body, opts = {}) {
    const auth = opts.auth !== false;
    const headers = {};

    if (auth) {
      const token = await this._ensureToken();
      headers.Authorization = `Bearer ${token}`;
    }

    const res = await this._rawRequest(method, path, body, headers);
    const parsed = res.body;

    if (!parsed || parsed.success === false || res.status >= 400) {
      const message = (parsed && parsed.message) || `Request failed with HTTP status ${res.status}`;
      const code = (parsed && parsed.error) || 'RequestFailed';
      throw new DigitalPayeError(code, message, res.status, parsed && parsed.details);
    }

    return { data: parsed.data, meta: parsed.meta, message: parsed.message };
  }

  // ── Raw HTTP request (no dependencies — uses Node's built-in http/https) ──
  _rawRequest(method, path, body, extraHeaders) {
    return new Promise((resolve, reject) => {
      const url = new URL(this.baseUrl + path);
      const lib = url.protocol === 'http:' ? http : https;
      const payload = body ? JSON.stringify(body) : null;

      const headers = Object.assign(
        { 'Content-Type': 'application/json', Accept: 'application/json' },
        extraHeaders
      );
      if (payload) headers['Content-Length'] = Buffer.byteLength(payload);

      const req = lib.request(
        {
          hostname: url.hostname,
          port: url.port || (url.protocol === 'http:' ? 80 : 443),
          path: url.pathname + url.search,
          method,
          headers,
          timeout: this.timeout,
        },
        (res) => {
          let raw = '';
          res.on('data', (chunk) => { raw += chunk; });
          res.on('end', () => {
            let parsed = null;
            if (raw) {
              try { parsed = JSON.parse(raw); } catch (e) { parsed = null; }
            }
            resolve({ status: res.statusCode, body: parsed });
          });
        }
      );

      req.on('timeout', () => req.destroy(new Error(`Request to ${path} timed out after ${this.timeout}ms`)));
      req.on('error', reject);
      if (payload) req.write(payload);
      req.end();
    });
  }
}

module.exports = Client;
